int TXT_Gamble_SortFunction(LPCVOID pParam1, LPCVOID pParam2) {
    if (*(uint32_t*)((int)pParam1 + 4) > *(uint32_t*)((int)pParam2 + 4)) {
      return 1;
    }

    return -(uint32_t)(*(uint32_t*)((int)pParam2 + 4) > *(uint32_t*)((int)pParam1 + 4));
}

// One-time loader for gamble.txt. Compiles the binary "gamble" table (code field only), resolves each item code to a class id via the items link, then sorts the entries by level and builds two side-tables: GambleTable (sorted class-id array) and gnItemTblsCacheSize (per-level upper-bound cache for [1..99]).
// @sourcefile .\DATATBLS\ItemTbls.cpp
void __fastcall TXT_AllocTxt_gamble(D2PoolManagerStrc * pMemory) {
    // Static local variables (originally global data)
    static int gnItemTblsCacheSize[100] = {}; D2_STATIC_GUARD(gnItemTblsCacheSize, "D2Common::DATATBLS::ItemTbls::TXT_AllocTxt_gamble::gnItemTblsCacheSize");

    int32_t nItemClassId;
    int nLevelCacheIdx;
    int* pGambleEntry;
    int nIdx;
    D2BinFieldInputStrc gamble[2];
    gamble[0].szName = "code";
    gamble[0].eType = FIELDTYPE_RAW4;
    gamble[0].nSize = 0;
    gamble[0].nOffset = 0;
    gamble[0].fpLinker = 0;
    gamble[1].szName = "end";
    gamble[1].eType = FIELDTYPE_END;
    gamble[1].nSize = 0;
    gamble[1].nOffset = 0;
    gamble[1].fpLinker = 0;
    D2GambleTxt* pTxtGamble = (D2GambleTxt*)DataTbls::CompileTxt(pMemory, "gamble", gamble, &nTxtGambleSize.nSize, 0xc);
    if (nTxtGambleSize.nSize) {
      nTxtGambleSize.pTable = D2_ALLOC_POOL_AT(nullptr, nTxtGambleSize.nSize * 4, ".\\DATATBLS\\ItemTbls.cpp", 0x7db);
      nIdx = 0;
      if (0 < nTxtGambleSize.nSize) {
        pGambleEntry = &pTxtGamble->nItemClassId;
        do {
          nItemClassId = Fog::Src::Excel::GetClassIdFromName(sgtDataTable.sTxtItemsLink, *(uint32_t*)((D2GambleTxt*)(pGambleEntry - 2))->szCode, 0);
          if (nItemClassId < 0 || !(gsItemsTable.pItems + nItemClassId)) {
            Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x7e0);
            exit(-1);
          }

          pGambleEntry[-1] = (uint32_t)(uint8_t)gsItemsTable.pItems[nItemClassId].nLevel;
          *pGambleEntry = nItemClassId;
          nIdx++;
          pGambleEntry += 3;
        } while (nIdx < nTxtGambleSize.nSize);
      }

      qsort(pTxtGamble, nTxtGambleSize.nSize, 0xc, TXT_Gamble_SortFunction);
    } else {
      nTxtGambleSize.pTable = 0;
    }

    nIdx = 0;
    if (0 < nTxtGambleSize.nSize) {
      pGambleEntry = &pTxtGamble->nItemClassId;
      do {
        *(int*)((int)nTxtGambleSize.pTable + nIdx * 4) = *pGambleEntry;
        nIdx++;
        pGambleEntry += 3;
      } while (nIdx < nTxtGambleSize.nSize);
    }

    gnItemTblsCacheSize[0] = 2;
    nIdx = 1;
    do {
      gnItemTblsCacheSize[nIdx] = nTxtGambleSize.nSize;
      nLevelCacheIdx = 0;
      if (0 < nTxtGambleSize.nSize) {
        pGambleEntry = &pTxtGamble->nLevel;
        do {
          if (nIdx < *pGambleEntry) {
            gnItemTblsCacheSize[nIdx] = nLevelCacheIdx;
            break;
          }

          nLevelCacheIdx++;
          pGambleEntry += 3;
        } while (nLevelCacheIdx < nTxtGambleSize.nSize);
      }

      nIdx++;
      if (nIdx >= 100) {
        DataTbls::UnloadBin(pTxtGamble);
        return;
      }
    } while (true);
}

